from collections import deque

def shortest_reaching(nums: list[int], k: int) -> int:
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)
    best = len(nums) + 1
    starts = deque()                     # start indices, prefix values increasing
    for j, p in enumerate(prefix):
        while starts and p - prefix[starts[0]] >= k:
            best = min(best, j - starts.popleft())   # no later end can beat this
        while starts and prefix[starts[-1]] >= p:
            starts.pop()                 # j starts later and no higher: better
        starts.append(j)
    return best if best <= len(nums) else -1

perf.naive:
def shortest_reaching(nums: list[int], k: int) -> int:
    best = -1
    for i in range(len(nums)):
        total = 0
        for j in range(i, len(nums)):
            total += nums[j]
            if total >= k:
                if best == -1 or j - i + 1 < best:
                    best = j - i + 1
                break
    return best
